  <script>
  const LOCATIONS_DATA=@json($locations);
  function ariRotaApp(){return{activeFilter:'tumu',layers:{yogunluk:false,ilaclama:false,radar:false},selectedLocation:null,visibleCount:0,showCheckinModal:false,showPricingModal:false,showReportModal:false,weatherLoading:false,checkinLoading:false,aksValidated:false,checkin:{region_id:'',aks_no:'',lat:'',lng:'',kovan_sayisi:100,photo_name:''},report:{sorun:''},toast:{show:false,message:''},map:null,markers:[],circles:[],layersOnMap:[],dynamicMarkers:[],allLocations:LOCATIONS_DATA,initApp(){this.$nextTick(()=>this.initMap())},statusCount(c){return this.allLocations.filter(l=>l.renk===c).length},statusLabel(s){return{uygun:'Uygun rota',uyari:'İzleme gerekli',riskli:'Dikkat gerekli'}[s]||'Güncel durum'},initMap(){this.map=L.map('map',{center:[38.18,27.85],zoom:8,zoomControl:false,attributionControl:false});L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19}).addTo(this.map);L.control.zoom({position:'bottomright'}).addTo(this.map);this.renderMarkers(this.allLocations);setTimeout(()=>this.map.invalidateSize(),150)},clearMap(){[...this.markers,...this.circles,...this.layersOnMap].forEach(i=>this.map.removeLayer(i));this.markers=[];this.circles=[];this.layersOnMap=[]},renderMarkers(locations){if(!this.map)return;this.clearMap();this.visibleCount=locations.length;locations.forEach(loc=>{const colors={yesil:'#5e8b62',sari:'#d88922',kirmizi:'#b95240'},color=colors[loc.renk]||colors.sari,pct=loc.kapasite_mevcut/loc.kapasite_max,circle=L.circle([loc.lat,loc.lng],{radius:15000,color,fillColor:color,fillOpacity:.07,weight:1,opacity:.46}).addTo(this.map);this.circles.push(circle);if(this.layers.yogunluk){const x=L.circle([loc.lat,loc.lng],{radius:28000,color,fillColor:color,fillOpacity:.08,weight:0}).addTo(this.map);this.layersOnMap.push(x)}if(this.layers.ilaclama&&loc.ilaclama_riski){const x=L.circle([loc.lat,loc.lng],{radius:9000,color:'#b95240',fillColor:'#b95240',fillOpacity:.14,weight:2,dashArray:'4,5'}).addTo(this.map);this.layersOnMap.push(x)}if(this.layers.radar){const x=L.circle([loc.lat,loc.lng],{radius:36000,color:'#7893a0',fillOpacity:0,weight:1,dashArray:'3,7'}).addTo(this.map);this.layersOnMap.push(x)}const icon=L.divIcon({className:'',html:`<div class="marker ${loc.renk==='yesil'?'ok':loc.renk==='kirmizi'?'risk':'warn'}">♢</div>`,iconSize:[30,30],iconAnchor:[15,15]}),marker=L.marker([loc.lat,loc.lng],{icon}).addTo(this.map);marker.bindPopup(`<strong style="font-size:13px">${loc.baslik}</strong><br><span style="font-size:12px;color:#647268">${loc.flora} · ${loc.rakım} m</span>`);marker.on('click',()=>{this.selectedLocation=loc;this.map.flyTo([loc.lat,loc.lng],10,{duration:.8})});this.markers.push(marker)})},setFilter(f){this.activeFilter=f;const list=f==='tumu'?this.allLocations:this.allLocations.filter(l=>l.mevsim===f);this.renderMarkers(list);if(this.selectedLocation&&!list.some(l=>l.id===this.selectedLocation.id))this.selectedLocation=null},toggleLayer(l){this.layers[l]=!this.layers[l];this.setFilter(this.activeFilter)},syncRegionCoords(){const r=this.allLocations.find(l=>String(l.id)===String(this.checkin.region_id));if(r){this.checkin.lat=r.lat;this.checkin.lng=r.lng}},validateAKS(){this.aksValidated=this.checkin.aks_no.length>=10},handlePhotoUpload(e){const f=e.target.files[0];if(f)this.checkin.photo_name=f.name},async submitCheckin(){if(!this.checkin.aks_no||!this.checkin.lat||!this.checkin.lng){this.showToast('AKS numarası ve koordinatları ekleyin.');return}this.checkinLoading=true;await new Promise(r=>setTimeout(r,700));const lat=parseFloat(this.checkin.lat),lng=parseFloat(this.checkin.lng);if(!isNaN(lat)&&!isNaN(lng)){const m=L.marker([lat,lng]).addTo(this.map).bindPopup('<strong>Yeni kovan noktası</strong>').openPopup();this.dynamicMarkers.push(m);this.map.flyTo([lat,lng],11)}this.checkinLoading=false;this.showCheckinModal=false;this.showToast('Konum haritaya eklendi.');this.checkin={aks_no:'',lat:'',lng:'',kovan_sayisi:100,photo_name:''}},openReport(){if(!this.selectedLocation){this.showToast('Önce haritadan bir rota seçin.');return}this.report.sorun='';this.showReportModal=true},async submitReport(){if(!this.report.sorun){this.showToast('Bildirim türünü seçin.');return}this.showReportModal=false;this.showToast('Saha bildiriminiz alındı.')},async refreshWeather(loc){if(!loc||this.weatherLoading)return;this.weatherLoading=true;try{const url=`https://api.open-meteo.com/v1/forecast?latitude=${loc.lat}&longitude=${loc.lng}&current=temperature_2m,relative_humidity_2m,wind_speed_10m,weather_code&timezone=Europe/Istanbul`,d=await(await fetch(url)).json();if(d.current){loc.sicaklik=Math.round(d.current.temperature_2m);loc.nem=Math.round(d.current.relative_humidity_2m);loc.ruzgar=Math.round(d.current.wind_speed_10m);this.showToast('Hava verisi yenilendi.')}}catch(e){this.showToast('Hava verisi şu an yenilenemedi.')}finally{this.weatherLoading=false}},showToast(message){this.toast={show:true,message};setTimeout(()=>this.toast.show=false,3000)}}}
  </script>
</body></html>
